item.stdout:
plugins {
    id 'java'
    id 'org.springframework.boot' version '3.5.16'
}

group = 'com.example'
version = '0.1.0'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    implementation platform('org.springframework.boot:spring-boot-dependencies:3.5.16')
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-validation'
    implementation 'org.springframework.boot:spring-boot-starter-jdbc'
    implementation 'org.springframework.boot:spring-boot-starter-actuator'
    runtimeOnly 'com.mysql:mysql-connector-j'
    runtimeOnly 'com.h2database:h2'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
}

tasks.named('test') {
    useJUnitPlatform()
    testLogging {
        events 'passed', 'skipped', 'failed'
    }
}

tasks.named('bootJar') {
    archiveFileName = 'app.jar'
}

tasks.named('jar') {
    enabled = false
}
rootProject.name = 'gitcangku1'
org.gradle.caching=true
org.gradle.jvmargs=-Xmx1g -Dfile.encoding=UTF-8
org.gradle.daemon=false
spring:
  application:
    name: gitcangku1
  config:
    import: "optional:configtree:/run/secrets/"
  datasource:
    # 榛樿浣跨敤宓屽叆寮?H2锛圡ySQL 鍏煎妯″紡锛夛紝鏁版嵁浠呭湪 JVM 鐢熷懡鍛ㄦ湡淇濈暀锛?    # 濡傞渶澶栭儴鏁版嵁搴擄紝鍙敤 DB_URL/DB_USER/DB_PASSWORD 瑕嗙洊銆?    url: ${DB_URL:jdbc:h2:mem:blindexp;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000}
    username: ${DB_USER:sa}
    password: ${DB_PASSWORD:}
    driver-class-name: ${DB_DRIVER:org.h2.Driver}
    hikari:
      maximum-pool-size: 5
      minimum-idle: 1
      connection-timeout: 10000
      validation-timeout: 3000
  sql:
    init:
      # 浠呭唴宓屽簱锛堥粯璁?H2锛夎嚜鍔ㄦ墽琛?schema.sql锛涘閮?MySQL 鍏ュ彛涓嶆墽琛?H2 鏂硅█鑴氭湰銆?      mode: embedded
  jackson:
    time-zone: Asia/Shanghai
  lifecycle:
    timeout-per-shutdown-phase: 20s

server:
  port: 8080
  shutdown: graceful
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health
  endpoint:
    health:
      show-details: never
-- 瀹為獙鐩叉硶鍒嗛厤琛ㄧ粨鏋勶紱杩愯浜?H2 MySQL 鍏煎妯″紡锛屾暟鎹粎鍦?JVM 鐢熷懡鍛ㄦ湡鍐呬繚鐣欍€?
CREATE TABLE IF NOT EXISTS experiment (
    id          VARCHAR(64)  NOT NULL,
    block_count INT          NOT NULL,
    status      VARCHAR(16)  NOT NULL,
    created_at  BIGINT       NOT NULL,
    CONSTRAINT pk_experiment PRIMARY KEY (id),
    CONSTRAINT ck_experiment_block_count CHECK (block_count BETWEEN 2 AND 8),
    CONSTRAINT ck_experiment_status CHECK (status IN ('OPEN', 'CLOSED'))
);
COMMENT ON TABLE  experiment IS '瀹為獙琛紝experimentId 鍏ㄥ眬鍞竴锛屽垱寤哄悗鍖虹粍鏁伴噺涓庡腑浣嶅唴瀹逛笉鍙慨鏀?;
COMMENT ON COLUMN experiment.id IS '瀹為獙缂栧彿锛屼笟鍔″敮涓€锛屽垱寤烘椂鐢辫姹傜粰瀹?;
COMMENT ON COLUMN experiment.block_count IS '鍖虹粍鏁伴噺锛屽彇鍊?~8锛屽垱寤烘椂鍥哄畾锛屾瘡缁勫浐瀹?涓腑浣?;
COMMENT ON COLUMN experiment.status IS '瀹為獙鐘舵€侊細OPEN=寮€鏀剧櫥璁帮紱CLOSED=宸插叧闂紝鍏抽棴鍚庢嫆缁濇柊澧炲垎閰?;
COMMENT ON COLUMN experiment.created_at IS '鍒涘缓鏃堕棿锛孶nix 姣锛孶TC';

CREATE TABLE IF NOT EXISTS seat (
    experiment_id VARCHAR(64) NOT NULL,
    block_no      INT         NOT NULL,
    seat_no       INT         NOT NULL,
    treatment     VARCHAR(1)  NOT NULL,
    CONSTRAINT pk_seat PRIMARY KEY (experiment_id, block_no, seat_no),
    CONSTRAINT ck_seat_block_no CHECK (block_no >= 1),
    CONSTRAINT ck_seat_seat_no CHECK (seat_no BETWEEN 1 AND 4),
    CONSTRAINT ck_seat_treatment CHECK (treatment IN ('A', 'B'))
);
COMMENT ON TABLE  seat IS '甯綅琛紙澶勭悊鏄犲皠锛夛細姣忓尯缁?甯紝鎸夋彁浜ら『搴忓浐瀹氫袱涓狝涓や釜B锛屼箣鍚庝笉鍙敼锛涗粎淇濆瓨浜庢暟鎹簱';
COMMENT ON COLUMN seat.experiment_id IS '鎵€灞炲疄楠岀紪鍙?;
COMMENT ON COLUMN seat.block_no IS '鍖虹粍鍙凤紝浠?寮€濮嬶紝鎸夊尯缁勯『搴忓垎閰?;
COMMENT ON COLUMN seat.seat_no IS '鍖虹粍鍐呭腑浣嶅彿1~4锛屽睘浜庡彲鐩存帴瑙ｇ爜淇℃伅锛岀姝㈤€氳繃鏅€氭帴鍙ｆ毚闇?;
COMMENT ON COLUMN seat.treatment IS '澶勭悊浠ｇ爜 A 鎴?B锛岀洸搴曪紝浠呮彮鐩叉壒鍑嗗悗鍙繑鍥炵粰鐢宠浜?;

CREATE TABLE IF NOT EXISTS allocation (
    id             BIGINT       NOT NULL AUTO_INCREMENT,
    experiment_id  VARCHAR(64)  NOT NULL,
    participant_id VARCHAR(64)  NOT NULL,
    block_no       INT          NOT NULL,
    seat_no        INT          NOT NULL,
    blind_code     VARCHAR(32)  NOT NULL,
    status         VARCHAR(16)  NOT NULL,
    assigned_actor VARCHAR(64)  NOT NULL,
    assigned_at    BIGINT       NOT NULL,
    withdrawn_at   BIGINT,
    CONSTRAINT pk_allocation PRIMARY KEY (id),
    CONSTRAINT uq_allocation_participant UNIQUE (experiment_id, participant_id),
    CONSTRAINT uq_allocation_seat UNIQUE (experiment_id, block_no, seat_no),
    CONSTRAINT uq_allocation_blind_code UNIQUE (blind_code),
    CONSTRAINT ck_allocation_status CHECK (status IN ('ASSIGNED', 'WITHDRAWN'))
);
COMMENT ON TABLE  allocation IS '鍙備笌鑰呭垎閰嶈〃锛涘悓瀹為獙鍚屽弬涓庤€呭彧鍗犱竴甯紝閫€缁勪笉閲婃斁甯綅銆佷笉閲嶆帓宸叉湁鍒嗛厤';
COMMENT ON COLUMN allocation.id IS '鍒嗛厤鑷涓婚敭';
COMMENT ON COLUMN allocation.experiment_id IS '鎵€灞炲疄楠岀紪鍙?;
COMMENT ON COLUMN allocation.participant_id IS '鍚堟垚鍙備笌鑰呯紪鍙凤紝闈炵湡瀹炲尰鐤楁暟鎹?;
COMMENT ON COLUMN allocation.block_no IS '鍒嗛厤鍒扮殑鍖虹粍鍙凤紝鏅€氭煡璇㈠彲杩斿洖';
COMMENT ON COLUMN allocation.seat_no IS '鍒嗛厤鍒扮殑甯綅鍙凤紝鍙洿鎺ヨВ鐮佸鐞嗕唬鐮侊紝绂佹閫氳繃鏅€氭帴鍙ｆ毚闇?;
COMMENT ON COLUMN allocation.blind_code IS '闅忔満鐢熸垚鐨勬棤鍚箟鐩茬爜锛屽叏灞€鍞竴锛屼笌鍖虹粍/甯綅鏃犲搴旇寰?;
COMMENT ON COLUMN allocation.status IS '鍒嗛厤鐘舵€侊細ASSIGNED=鍦ㄧ粍锛沇ITHDRAWN=宸查€€缁勶紙甯綅浠嶄繚鐣欙級';
COMMENT ON COLUMN allocation.assigned_actor IS '鎵ц鐧昏鐨勬搷浣滆€呯紪鍙凤紙X-Actor-Id锛?;
COMMENT ON COLUMN allocation.assigned_at IS '鍒嗛厤鏃堕棿锛孶nix 姣锛孶TC';
COMMENT ON COLUMN allocation.withdrawn_at IS '閫€缁勬椂闂达紝Unix 姣锛孶TC锛汵ULL 琛ㄧず鏈€€缁?;

CREATE TABLE IF NOT EXISTS unblind_request (
    id                      VARCHAR(64)  NOT NULL,
    experiment_id           VARCHAR(64)  NOT NULL,
    participant_id          VARCHAR(64)  NOT NULL,
    allocation_id           BIGINT       NOT NULL,
    reason                  VARCHAR(500) NOT NULL,
    applicant_actor         VARCHAR(64)  NOT NULL,
    reviewer_actor          VARCHAR(64),
    status                  VARCHAR(16)  NOT NULL,
    treatment               VARCHAR(1),
    created_at              BIGINT       NOT NULL,
    reviewed_at             BIGINT,
    pending_allocation_id   BIGINT,
    CONSTRAINT pk_unblind_request PRIMARY KEY (id),
    CONSTRAINT uq_unblind_pending UNIQUE (pending_allocation_id),
    CONSTRAINT ck_unblind_status CHECK (status IN ('PENDING', 'APPROVED')),
    CONSTRAINT ck_unblind_treatment CHECK (treatment IS NULL OR treatment IN ('A', 'B'))
);
COMMENT ON TABLE  unblind_request IS '鎻洸鐢宠琛紱鍚屼竴鍒嗛厤鑷冲涓€涓緟瀹＄敵璇凤紝椤荤敱鍙︿竴鍚?REVIEWER 鎵瑰噯鍚庣敵璇蜂汉鏂瑰彲鏌ョ湅缁撴灉';
COMMENT ON COLUMN unblind_request.id IS '鎻洸鐢宠缂栧彿锛屽叏灞€鍞竴';
COMMENT ON COLUMN unblind_request.experiment_id IS '鎵€灞炲疄楠岀紪鍙?;
COMMENT ON COLUMN unblind_request.participant_id IS '琚敵璇锋彮鐩茬殑鍚堟垚鍙備笌鑰呯紪鍙?;
COMMENT ON COLUMN unblind_request.allocation_id IS '瀵瑰簲鍒嗛厤涓婚敭';
COMMENT ON COLUMN unblind_request.reason IS '鎻洸鍘熷洜锛屽繀濉紝闈炵┖';
COMMENT ON COLUMN unblind_request.applicant_actor IS '鐢宠浜烘搷浣滆€呯紪鍙凤紝椤讳负 COORDINATOR锛屼笖鍙湁鍏舵湰浜鸿兘鏌ヨ鎻洸缁撴灉';
COMMENT ON COLUMN unblind_request.reviewer_actor IS '鎵瑰噯鐨?REVIEWER 鎿嶄綔鑰呯紪鍙凤紝蹇呴』涓嶅悓浜庣敵璇蜂汉锛涙湭鎵瑰噯鏃朵负 NULL';
COMMENT ON COLUMN unblind_request.status IS '鐢宠鐘舵€侊細PENDING=寰呭锛汚PPROVED=宸叉壒鍑?;
COMMENT ON COLUMN unblind_request.treatment IS '鎻洸缁撴灉澶勭悊浠ｇ爜 A/B锛屾壒鍑嗘椂鍐欏叆锛汵ULL=灏氭湭鎵瑰噯';
COMMENT ON COLUMN unblind_request.created_at IS '鐢宠鏃堕棿锛孶nix 姣锛孶TC';
COMMENT ON COLUMN unblind_request.reviewed_at IS '鎵瑰噯鏃堕棿锛孶nix 姣锛孶TC锛汵ULL 琛ㄧず鏈壒鍑?;
COMMENT ON COLUMN unblind_request.pending_allocation_id IS '寰呭鍘婚噸鍒楋細寰呭鏃剁瓑浜?allocation_id锛岀粓鎬佺疆 NULL锛涘敮涓€绱㈠紩淇濊瘉鍚屼竴鍒嗛厤鑷冲涓€涓緟瀹＄敵璇?;

CREATE TABLE IF NOT EXISTS idempotent_request (
    request_id      VARCHAR(64)  NOT NULL,
    actor_id        VARCHAR(64)  NOT NULL,
    role            VARCHAR(16)  NOT NULL,
    operation       VARCHAR(64)  NOT NULL,
    fingerprint     VARCHAR(128) NOT NULL,
    response_status INT          NOT NULL,
    response_body   CLOB,
    created_at      BIGINT       NOT NULL,
    CONSTRAINT pk_idempotent_request PRIMARY KEY (request_id)
);
COMMENT ON TABLE  idempotent_request IS '鍐欐搷浣滃箓绛夎褰曡〃锛涗粎璁板綍鎴愬姛璇锋眰锛屽け璐ヤ笉鍗犻敭锛屼笌涓氬姟鍙樻洿鍚屼竴浜嬪姟鍘熷瓙鎻愪氦';
COMMENT ON COLUMN idempotent_request.request_id IS '鍏ㄥ眬鍞竴 requestId锛圶-Request-Id锛?;
COMMENT ON COLUMN idempotent_request.actor_id IS '棣栨鎴愬姛璋冪敤鐨勬搷浣滆€呯紪鍙凤紝灞炰簬骞傜瓑鍙傛暟鐨勪竴閮ㄥ垎';
COMMENT ON COLUMN idempotent_request.role IS '棣栨鎴愬姛璋冪敤鐨勮鑹?COORDINATOR/REVIEWER锛屽睘浜庡箓绛夊弬鏁扮殑涓€閮ㄥ垎';
COMMENT ON COLUMN idempotent_request.operation IS '鍐欐搷浣滄爣璇嗭紝濡?experiment.create/allocation.create';
COMMENT ON COLUMN idempotent_request.fingerprint IS '璇锋眰鍙傛暟鎸囩汗锛堝惈璺緞鍙傛暟涓庤姹備綋锛夛紝涓?actor/role 鍏卞悓鍒ゅ畾鍚屽弬/寮傚弬';
COMMENT ON COLUMN idempotent_request.response_status IS '棣栨鎴愬姛鍝嶅簲鐨?HTTP 鐘舵€佺爜锛岄噸鏀炬椂鍘熸牱杩斿洖';
COMMENT ON COLUMN idempotent_request.response_body IS '棣栨鎴愬姛鍝嶅簲浣?JSON锛岄噸鏀炬椂鍘熸牱杩斿洖';
COMMENT ON COLUMN idempotent_request.created_at IS '璁板綍鏃堕棿锛孶nix 姣锛孶TC';
# 娴嬭瘯閰嶇疆锛氫娇鐢ㄧ嫭绔嬪懡鍚嶇殑 H2 鍐呭瓨搴擄紙MySQL 鍏煎妯″紡锛夛紝涓嶄緷璧栦换浣曞閮ㄦ暟鎹簱銆?spring:
  datasource:
    url: jdbc:h2:mem:blindexp_test;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1
    username: sa
    password:
    driver-class-name: org.h2.Driver
  sql:
    init:
      mode: always
  jackson:
    time-zone: Asia/Shanghai

logging:
  level:
    root: warn

